CREATE SCHEMA IF NOT EXISTS reportes;
CREATE TABLE IF NOT EXISTS reportes.client_tokens (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    client text NOT NULL UNIQUE,
    token_hash text NOT NULL,
    active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    rotated_at timestamptz,
    notes text
);
CREATE TABLE IF NOT EXISTS reportes.snapshots (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    client text NOT NULL,
    week text NOT NULL,
    r2_key text NOT NULL,
    content_hash text,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT snapshots_client_week_uniq UNIQUE (client, week)
);
CREATE INDEX IF NOT EXISTS snapshots_client_idx ON reportes.snapshots (client, week DESC);
COMMENT ON SCHEMA reportes IS 'NAT-116/117 client reports. Isolated from public by design.';
